CREATE TABLE t1(a); INSERT INTO t1 VALUES(NULL),(1); CREATE TABLE sfi_result(seq,label,tp,v); INSERT INTO sfi_result SELECT 1,'1:',typeof(a),a FROM t1 WHERE a<10; INSERT INTO sfi_result SELECT 2,'2:',typeof(a),a FROM t1 WHERE a+0<10; CREATE INDEX t1x1 ON t1(a); CREATE INDEX t1x2 ON t1(a+0); INSERT INTO sfi_result SELECT 3,'3:',typeof(a),a FROM t1 WHERE a<10; INSERT INTO sfi_result SELECT 4,'4:',typeof(a),a FROM t1 WHERE a+0<10;